const { body } = $input.first().json;
if (body?.event !== 'maintenance.sharing_approved' || typeof body.case_id !== 'string' || !body.case_id.trim()) {
  throw new Error('Expected a maintenance.sharing_approved event with a case ID');
}
const { order } = body;
if (order?.schema_version !== '1.0' || order.request_id !== body.case_id || typeof order.idempotency_key !== 'string' || !order.idempotency_key.trim()) {
  throw new Error('Expected a connector v1 order for this case with a stable idempotency key');
}
return [{ json: order }];

const { job_id, duplicate } = $input.first().json;
if (typeof job_id !== 'string' || !job_id.trim()) {
  throw new Error('HeatFix did not return a job ID');
}
const { request_id } = $('Validate event').first().json;
return [{ json: { case_id: request_id, job_id, duplicate: duplicate === true } }];
